/** Texte traduit ; `{n}` etc. remplacés par `params`. Clé manquante dans une langue : repli FR puis la clé. */
export function t(langue, cle, params = {}) {
  const lire = (l) => cle.split('.').reduce((o, k) => (o == null ? o : o[k]), textes[l]);
  const brut = lire(langue) ?? lire('fr') ?? cle;
  return typeof brut === 'string' ? brut.replace(/\{(\w+)\}/g, (m, k) => (k in params ? String(params[k]) : m)) : cle;
}
